const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97753f") }, {"long_answer": "El Plan Estratégico para la Eliminación del Sarampión y la Rubeola recomienda que el manejo clínico y epidemiológico de cada caso sospechoso siga los protocolos de vigilancia de la Red Nacional de Vigilancia Epidemiológica (RENAVE), que establecen la notificación urgente, la toma de muestras para confirmación por laboratorio, el aislamiento del caso, el estudio de contactos y la vacunación o inmunoglobulina posexposición de los susceptibles. Diagnosticar solo por la clínica o realizar únicamente la IgM es insuficiente, porque la confirmación debe incluir también detección del genoma viral, y prescindir de estudios de laboratorio impediría clasificar correctamente los casos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977540") }, {"long_answer": "En la fase de eliminación, la confirmación de los casos sospechosos mediante diagnóstico molecular (RT-PCR y genotipado) permite clasificarlos adecuadamente como confirmados o descartados, como importados o autóctonos, y conocer las cadenas de transmisión. Esta información es imprescindible para documentar ante la OMS que no existe transmisión endémica y justificar así la situación del país en el proceso de eliminación del sarampión. No tiene como finalidad determinar el tratamiento, puesto que no existe un antiviral específico, ni obtener compensaciones económicas, y aunque la vigilancia contribuye a controlar la propagación, ese no es el objetivo específico de la confirmación molecular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977543") }, {"long_answer": "El Plan Estratégico para la Eliminación del Sarampión y la Rubeola incluye la formación y la comunicación como líneas de trabajo cuyo propósito es proporcionar a profesionales y población información equilibrada que despeje las dudas y percepciones erróneas sobre la seguridad y los efectos adversos de las vacunas, para mantener la confianza y las altas coberturas. En España la vacunación no es obligatoria, por lo que el plan no persigue imponerla. Tampoco se basa en campañas publicitarias genéricas ni en infundir miedo, ya que una comunicación alarmista resulta contraproducente y la evidencia respalda una información veraz, clara y basada en datos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977546") }, {"long_answer": "El Comité Nacional de Verificación de la eliminación del sarampión y la rubeola revisa la información epidemiológica, de laboratorio y de coberturas vacunales de España y elabora el informe anual que se remite a la Comisión Regional de Verificación de la OMS para Europa. Entre sus objetivos figura proponer mejoras en las actividades para la consecución y el mantenimiento de la eliminación. La Comisión Regional de Verificación la constituye la OMS, no el comité nacional; el informe anual es una función del comité, no un objetivo en sí; y la difusión en congresos es una actividad complementaria, no uno de sus objetivos definidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97754a") }, {"long_answer": "Para el aislamiento y la detección del virus del sarampión o de la rubeola, las muestras clínicas (exudado faríngeo, orina) deben recogerse lo antes posible tras la aparición del exantema, y el periodo óptimo son los primeros 4 días, cuando la excreción viral es máxima y la probabilidad de aislar el virus y genotiparlo es mayor. A partir del cuarto día la excreción disminuye progresivamente. El intervalo de 7 a 14 días tras la vacunación se refiere a la posible aparición de reacciones a la vacuna, y los 28 días tras el exantema corresponden al periodo útil para detectar anticuerpos IgM en suero, no para el aislamiento viral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97754c") }, {"long_answer": "En la vigilancia molecular del sarampión y la rubeola, el genotipo es la unidad taxonómica definida a partir de las diferencias de nucleótidos entre cepas víricas, según los criterios de la OMS, que permite conocer el origen geográfico de los virus y distinguir casos importados de transmisión autóctona. Dos o más casos relacionados temporalmente y asociados epidemiológica o virológicamente constituyen un brote. El nombre asignado a una secuencia según el tipo de espécimen, la localidad, el país, la semana epidemiológica y el año es la denominación de la cepa, y un grupo de secuencias N450 idénticas define una variante dentro de un genotipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97754f") }, {"long_answer": "La flebitis se define como la inflamación de una vena debida a la alteración del endotelio provocada por la infusión endovenosa o por el propio catéter, que puede tener origen mecánico, químico o infeccioso. Se manifiesta con dolor, eritema, calor, induración y, en fases avanzadas, cordón venoso palpable, y las escalas de valoración visual permiten graduarla para retirar el catéter precozmente. No afecta a arterias, nervios ni músculos: la inflamación arterial se denomina arteritis, la de un nervio neuritis y la muscular miositis, procesos que no se relacionan con la terapia intravenosa periférica habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977550") }, {"long_answer": "En la escala de valoración visual de la flebitis, el nivel más alto, nivel 5, corresponde a flebitis con dolor, eritema, hinchazón y cordón venoso palpable de más de 6 cm desde la zona de inserción, con trombosis venosa, y puede asociar supuración. Indica tromboflebitis avanzada y obliga a retirar el catéter inmediatamente y a valorar tratamiento. El nivel 4 describe dolor, eritema, hinchazón y cordón venoso palpable de menos de 6 cm; el nivel 2 se caracteriza por dolor con eritema o hinchazón en la zona de inserción; y el nivel 1 es un dolor leve o eritema leve, que solo requiere vigilancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977554") }, {"long_answer": "La escala de valoración visual de la flebitis tiene como objetivo describir los distintos valores o grados de flebitis, desde la ausencia de signos hasta la tromboflebitis avanzada, de forma que todos los profesionales utilicen criterios homogéneos al inspeccionar la zona de inserción del catéter venoso periférico y puedan decidir cuándo vigilar o retirar el catéter. Es, por tanto, una herramienta de valoración de enfermería relacionada con la terapia intravenosa. No sirve para diagnosticar enfermedades respiratorias, evaluar la presión arterial ni calcular el índice de masa corporal, que requieren instrumentos y mediciones completamente distintos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977556") }, {"long_answer": "Según el documento de la escala de valoración visual de la flebitis, la revisión bibliográfica que sirvió de base para elaborarla se realizó en las bases de datos CINAHL, SciELO y Google Académico, que recogen literatura de enfermería y ciencias de la salud, incluida producción en español y latinoamericana. La combinación de PubMed, JSTOR y Web of Science, la de MEDLINE, Cochrane Library y Embase, o la de Academic Search Complete, PsycINFO e IEEE Xplore no son las fuentes citadas en el documento; además, PsycINFO e IEEE Xplore están orientadas a psicología e ingeniería, respectivamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977558") }, {"long_answer": "El dosímetro de muñeca es un dosímetro de extremidades que se coloca en la muñeca del trabajador expuesto cuando las manos o antebrazos se encuentran cerca del haz de radiación, por ejemplo en radiología intervencionista o en el manejo de radiofármacos. Permite estimar la dosis máxima recibida en extremidades y en piel, que puede ser muy superior a la registrada por el dosímetro de solapa o de tórax. Ese dosímetro corporal es el que estima la dosis a cuerpo completo, la exposición ambiental se mide con dosímetros de área y la dosis en órganos internos se calcula, no se mide con este dispositivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977563") }, {"question": "¿En qué dominio de la taxonomía NANDA-I se incluye la clase «Imagen corporal»?", "option_1": "Autopercepción", "option_2": "Rol/relaciones", "option_3": "Afrontamiento/tolerancia al estrés", "option_4": "Percepción/cognición", "answer": 1, "long_answer": "En la taxonomía II de NANDA-I, la clase «Imagen corporal» pertenece al dominio 6, Autopercepción, que agrupa la conciencia del propio yo en tres clases: autoconcepto, autoestima e imagen corporal. En ella se incluye, por ejemplo, el diagnóstico Trastorno de la imagen corporal. El dominio Rol/relaciones se refiere a los vínculos con otras personas, como cuidadores o familia; Afrontamiento/tolerancia al estrés abarca las respuestas postraumáticas, de afrontamiento y de estrés neurocomportamental; y Percepción/cognición incluye la atención, la orientación, la sensación-percepción, la cognición y la comunicación, sin clases sobre la imagen corporal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977569") }, {"option_1": "Antes de los 6 meses de edad: al inicio de la temporada o al nacer si nacen durante ella", "long_answer": "En el calendario común de vacunación e inmunización a lo largo de toda la vida, la inmunización frente al virus respiratorio sincitial con anticuerpo monoclonal (nirsevimab) se recomienda en todos los nacidos entre el 1 de abril del año de comienzo de la temporada y el 31 de marzo del año de fin, es decir, en menores de 6 meses al inicio o durante la temporada. Los nacidos antes de la temporada se inmunizan al inicio de esta, y los nacidos durante ella, preferentemente en las primeras 24-48 horas de vida. Esperar a los 12, 18 o 24 meses dejaría al lactante desprotegido en la etapa de mayor riesgo de bronquiolitis grave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97756c") }, {"answer": 3, "long_answer": "En el documento de vacunación en grupos de riesgo, a las personas de 5 años o más internas en centros de discapacidad o residentes en instituciones cerradas se les recomienda la vacunación antigripal con una dosis estacional cada temporada, dada la facilidad de transmisión en entornos cerrados y el mayor riesgo de complicaciones. La pauta de dos dosis separadas por cuatro semanas se reserva para menores de 9 años que se vacunan frente a la gripe por primera vez, no es la recomendación general de este grupo. La vacunación no está desaconsejada, sino expresamente indicada, y no existe una pauta de tres dosis para la gripe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977570") }, {"option_2": "Fiebre amarilla", "option_3": "Triple vírica tras el trasplante", "option_4": "Varicela tras el trasplante", "long_answer": "En el documento de vacunación en grupos de riesgo de adultos, la vacuna frente a la hepatitis B está indicada en personas con trasplante de órgano sólido o en espera de trasplante hepático, idealmente antes del trasplante para obtener mejor respuesta, con control serológico posterior. La fiebre amarilla, la triple vírica y la varicela son vacunas de virus vivos atenuados, contraindicadas tras el trasplante por la inmunosupresión farmacológica, y si se precisan deben administrarse antes del trasplante, con la antelación adecuada. Por ello, de las opciones presentadas solo la hepatitis B constituye una recomendación específica y segura para este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977572") }, {"question": "En adultos de grupos de riesgo, si se utiliza la vacuna frente a meningococo B MenB-fHbp (Trumenba), ¿cuántas dosis se administran en la primovacunación?", "long_answer": "En personas con condiciones de alto riesgo de enfermedad meningocócica invasiva, como asplenia, deficiencias del complemento o tratamiento con eculizumab, la vacuna MenB-fHbp (Trumenba) se administra en una pauta de primovacunación de tres dosis (0, 1-2 y 6 meses), pauta que proporciona mejor protección en estos grupos que la de dos dosis empleada en población sana. La vacuna 4CMenB (Bexsero), en cambio, se administra en adultos con dos dosis separadas al menos un mes. Una sola dosis es insuficiente y la pauta de cuatro dosis no existe en adultos; además se recomiendan dosis de recuerdo en los grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977573") }, {"long_answer": "En los adultos con condiciones de riesgo, la vacunación antineumocócica se individualiza según la patología de base y las vacunas disponibles, por lo que la recomendación es valorar una pauta secuencial adaptada a cada caso. Históricamente se usaba la conjugada 13-valente seguida de la polisacárida 23-valente, y actualmente se emplean conjugadas de mayor valencia, como la 20-valente, que pueden simplificar la pauta. La dosis en cada temporada estacional corresponde a la gripe, las dos dosis separadas cuatro semanas y la serología previa en mayores de 18 años sin antecedentes corresponden a la vacunación frente a la varicela, no al neumococo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977474") }, {"long_answer": "En el Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores, la primera actividad de coordinación, común a todos los escenarios de riesgo, es establecer en cada nivel administrativo un Comité Permanente encargado de la elaboración, el control y el seguimiento del Plan, que garantiza la participación de salud pública, sanidad ambiental, sanidad animal y asistencia. Establecer circuitos de aviso ante casos autóctonos de enfermedades transmitidas por Aedes se relaciona con la vigilancia, los simulacros con la preparación y respuesta, e integrar la información en el sistema de vigilancia es también una actividad propia del componente de vigilancia epidemiológica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977476") }, {"long_answer": "La gestión integrada del vector incluye, entre sus actividades por escenarios, realizar vigilancia entomológica rutinaria y en puntos de entrada, como puertos y aeropuertos, y apoyarse en métodos de ciencia ciudadana, por ejemplo aplicaciones móviles de notificación, para detectar precozmente nuevas introducciones de especies invasoras como Aedes albopictus o Aedes aegypti. Elaborar protocolos de manejo clínico de dengue, chikungunya, zika y fiebre amarilla pertenece al componente asistencial, los simulacros ante casos importados y autóctonos a la coordinación y preparación, y la información sobre repelentes y protección individual a la comunicación y educación sanitaria de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977479") }, {"long_answer": "El Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores tiene como finalidad reducir la carga y la amenaza que suponen para la salud humana las enfermedades transmitidas por vectores, y en el apartado dedicado a los mosquitos del género Culex se concreta en reducir las enfermedades humanas transmitidas por ellos, como la fiebre del Nilo Occidental. Las demás opciones son incompatibles con un plan de salud pública: aumentar la circulación del virus del Nilo Occidental o promover la cría de mosquitos irían en contra de sus fines, y la eliminación de Aedes japonicus no es su objetivo principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977486") }, {"long_answer": "El control integrado del vector se define como la combinación organizada de todas las estrategias disponibles, ambientales, físicas, biológicas, químicas y educativas, para reducir la abundancia del vector o eliminarlo, de forma racional y eficiente y con el menor impacto posible sobre el medio ambiente y las personas. No consiste en reducir la población de vectores de forma indiscriminada ni en utilizar exclusivamente métodos químicos, que generan resistencias y daños ambientales, y por definición busca evitar las medidas de gestión que afecten negativamente al medio ambiente y a la población, como el uso masivo de insecticidas sin valoración previa del riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977487") }, {"long_answer": "El control integrado del vector persigue que las medidas para reducir o eliminar el vector se apliquen de manera que se minimice su impacto sobre el medio ambiente y las personas, combinando métodos y empleando los productos químicos solo cuando están justificados por la valoración del riesgo. Su meta no es eliminar por completo la población de vectores a cualquier coste, lo que con frecuencia no es factible ni ambientalmente aceptable, ni aplicar métodos químicos agresivos, que favorecen las resistencias y dañan especies no diana. Aumentar la incidencia de picaduras e infecciones por arbovirus es justamente lo que se pretende evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977488") }, {"long_answer": "La vigilancia entomológica consiste en el seguimiento sistemático de la presencia, distribución, densidad y actividad de los vectores, y de la infección de estos por patógenos, con el fin de evaluar el riesgo de transmisión a la población y orientar las medidas de control. No se limita a zonas urbanas, ya que también incluye áreas rurales, humedales y puntos de entrada como puertos y aeropuertos. La aplicación de métodos químicos y el control biológico son medidas de control vectorial que se deciden a partir de los resultados de la vigilancia, pero no forman parte de la vigilancia en sí misma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97748a") }, {"long_answer": "La gestión integrada de plagas aplicada a los mosquitos culícidos es un proceso que incorpora la valoración del riesgo como punto de partida: se analiza la especie, su abundancia, los criadores, la población expuesta y el riesgo sanitario antes de decidir qué medidas aplicar, priorizando las no químicas. Aplicar métodos químicos de forma indiscriminada es contrario a este enfoque. Las aplicaciones puntuales de insecticidas y la revisión periódica de la efectividad son elementos que pueden formar parte del proceso, pero no definen en qué consiste la gestión integrada, cuyo rasgo distintivo es la incorporación de la evaluación del riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97748b") }, {"long_answer": "Culex pipiens, el mosquito común, es la especie de culícido más ampliamente distribuida en España y se encuentra en prácticamente todas las localidades de la península, en medios urbanos y rurales, excepto a gran altitud en la alta montaña. Es un vector relevante del virus del Nilo Occidental, ya que pica tanto a aves como a mamíferos. Culex modestus y Culex perexiguus tienen una distribución más restringida, ligada sobre todo a humedales y arrozales, como los de Andalucía o los deltas, y Aedes albopictus, el mosquito tigre, es una especie invasora cuya distribución, aunque en expansión, se concentra en el litoral mediterráneo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977497") }, {"long_answer": "El Tercer Reto Mundial por la Seguridad del Paciente de la OMS, «Medicación sin daño», establece tres áreas prioritarias: las situaciones de alto riesgo, la polimedicación y las transiciones asistenciales. Estas áreas no son mutuamente excluyentes porque un mismo paciente puede estar expuesto a varios riesgos de eventos adversos a la vez, por ejemplo una persona mayor polimedicada que recibe un medicamento de alto riesgo durante un cambio de nivel asistencial. No dependen de grupos de edad distintos, no son independientes entre sí, y la razón que se da no son factores externos, sino la coexistencia de riesgos en el mismo paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97749b") }, {"long_answer": "Los estudios recogidos en la literatura sobre conciliación muestran que, en pacientes mayores polimedicados, se han observado errores de conciliación al ingreso hospitalario de hasta el 67%, porque cuanto mayor es el número de medicamentos y de prescriptores, mayor es la probabilidad de omisiones, duplicidades o cambios de dosis no intencionados al elaborar las órdenes iniciales. Esta elevada frecuencia justifica que estos pacientes sean un grupo prioritario para la conciliación. Las cifras del 40%, 50% o 60% no coinciden con el dato recogido, aunque todas reflejan que se trata de un problema muy frecuente en esta población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a2") }, {"question": "¿Cuál es uno de los objetivos del Tercer Reto Mundial por la Seguridad del Paciente de la OMS, lanzado en 2017 bajo el lema «Medicación sin daño»?", "long_answer": "El Tercer Reto Mundial por la Seguridad del Paciente, «Medicación sin daño», lanzado por la OMS en 2017, se propuso reducir en un 50% en cinco años los daños graves y evitables relacionados con la medicación en todos los países, actuando sobre las situaciones de alto riesgo, la polimedicación y las transiciones asistenciales, ámbitos en los que la conciliación de la medicación desempeña un papel esencial. Las reducciones del 10%, 20% o 30% no corresponden a la meta fijada por la OMS, que planteó un objetivo ambicioso de reducción a la mitad de este tipo de daños."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a7") }, {"question": "¿Qué organismo estadounidense incluyó en 2005 la conciliación de la medicación entre sus objetivos nacionales de seguridad del paciente (National Patient Safety Goals)?", "option_1": "La Organización Panamericana de la Salud", "option_2": "La Agencia Europea del Medicamento", "option_3": "La Joint Commission", "option_4": "La Food and Drug Administration", "long_answer": "La Joint Commission, organismo de acreditación de centros sanitarios de Estados Unidos, incluyó en 2005 la conciliación de la medicación en las transiciones asistenciales entre sus objetivos nacionales de seguridad del paciente, lo que impulsó su implantación en los hospitales. Otros organismos, como el Institute for Healthcare Improvement, la OMS con el proyecto High 5s o la Massachusetts Coalition, también la han promovido. La Organización Panamericana de la Salud es un organismo regional, la Agencia Europea del Medicamento evalúa medicamentos en la Unión Europea y la FDA autoriza y supervisa medicamentos en Estados Unidos, pero ninguna estableció estos objetivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a9") }, {"long_answer": "El proyecto High 5s, impulsado por la OMS a través de su Centro Colaborador en Seguridad del Paciente, tenía como objetivo implantar procedimientos normalizados para cinco problemas de seguridad del paciente en al menos cinco países durante cinco años, y uno de ellos era la conciliación de la medicación en las transiciones asistenciales. Por eso se describe como un proyecto para promover la implantación de prácticas seguras de conciliación en cinco países. No era un proyecto de investigación sobre enfermedades infecciosas ni un programa de formación, y aunque contribuye a prevenir errores, su seña de identidad es la implantación de procedimientos estandarizados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ae") }, {"long_answer": "Los estudios sobre conciliación de la medicación coinciden en que el error más frecuente es la omisión de un medicamento, es decir, que el paciente deje de recibir un fármaco que tomaba habitualmente sin que exista una decisión clínica que lo justifique, con frecuencia por una historia farmacoterapéutica incompleta al ingreso. Los errores de dosis, de frecuencia o de vía de administración también aparecen, pero con menor frecuencia. Los problemas de comunicación son una causa que favorece los errores, no un tipo de error de conciliación en sí mismo, y por tanto no figuran en la clasificación de discrepancias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774af") }, {"long_answer": "Los estudios recogidos sobre conciliación al alta han detectado discrepancias de hasta el 75% entre los informes de alta hospitalaria y la medicación registrada por el médico de atención primaria, lo que demuestra que la transición del hospital al domicilio es un punto crítico para la seguridad. Estas discrepancias pueden deberse a cambios no comunicados, omisiones o duplicidades entre los medicamentos del hospital y los habituales del paciente. Por ello se recomienda conciliar al alta y comunicar de forma clara la medicación al paciente y a atención primaria. Las cifras del 30%, 40% o 50% no corresponden al máximo descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b7") }, {"long_answer": "Una discrepancia justificada no documentada es un cambio en la medicación que responde a una decisión clínica adecuada, pero que no se ha registrado. Aunque el cambio sea correcto, debe comunicarse al prescriptor para que lo confirme y quede registrado en la historia clínica, ya que la falta de documentación puede inducir errores en las transiciones posteriores, por ejemplo al alta o en atención primaria. Dejarla sin resolver, ignorarla y continuar con el proceso o no tomar ninguna acción perpetúan el riesgo, porque el siguiente profesional no sabrá si el cambio fue intencionado o un error de conciliación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b9") }, {"long_answer": "Según los datos de vigilancia epidemiológica del VIH en España recogidos en el Plan Estratégico para la Prevención y Control del VIH y las ITS, la transmisión sexual es la vía más frecuente de los nuevos diagnósticos, principalmente entre hombres que tienen sexo con hombres, seguida de la transmisión heterosexual. La transmisión por uso de drogas inyectadas, predominante en los años ochenta y noventa, representa hoy un porcentaje muy pequeño de los diagnósticos. La transmisión perinatal es excepcional gracias al cribado universal en el embarazo y al tratamiento antirretroviral, y la transmisión por transfusiones está prácticamente eliminada por el control de las donaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774be") }, {"long_answer": "El objetivo general del Plan Estratégico para la Prevención y Control de la Infección por el VIH y las ITS en España es impulsar y coordinar las acciones necesarias para eliminar el VIH y las ITS como problema de salud pública en 2030, en consonancia con los Objetivos de Desarrollo Sostenible y con las metas de ONUSIDA y la OMS. Mejorar la calidad de vida de las personas con VIH, promover la igualdad de derechos y reducir la discriminación asociada al VIH son objetivos y líneas de actuación que forman parte del plan, pero se subordinan a ese objetivo general de eliminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774bf") }, {"long_answer": "El Plan Estratégico para la Prevención y Control del VIH y las ITS aborda la promoción de la salud sexual integral desde un enfoque positivo de la sexualidad, entendida como fuente de bienestar y no solo como riesgo, y teniendo en cuenta los determinantes sociales de la salud y los contextos de vulnerabilidad que condicionan la exposición al VIH y a otras ITS. No se dirige únicamente a la población general, ya que contempla poblaciones clave como hombres que tienen sexo con hombres, personas que ejercen la prostitución o personas migrantes, ni se limita a la prevención del VIH, y el documento sí especifica su enfoque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c0") }, {"long_answer": "Entre las acciones de promoción de la salud sexual dirigidas a la población adolescente, adulta joven y a las gestantes, el Plan Estratégico para la Prevención y Control del VIH y las ITS incluye la promoción de la educación en sexualidad y de los buenos tratos, con un enfoque integral que aborda aspectos afectivos, de igualdad, consentimiento y prevención. La implementación de la PrEP y su sistema de información se dirige a personas con alto riesgo de adquirir el VIH, el abordaje multidisciplinar del chemsex se centra en hombres que tienen sexo con hombres, y la promoción del preservativo y del lubricante es una acción transversal de prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c8") }, {"answer": 2, "long_answer": "En el Plan Estratégico para la Prevención y Control del VIH y las ITS, el objetivo 3.4 se denomina Realización de un abordaje de problemas de salud emergentes o reemergentes en personas con el VIH, como nuevas infecciones, el chemsex o las comorbilidades ligadas al envejecimiento. La promoción de la innovación tecnológica en la provisión de servicios se enmarca en el objetivo 3.3, dedicado a la equidad, la accesibilidad y la innovación en la atención sanitaria. La evaluación del riesgo de COVID-19 en el personal sanitario no es un objetivo del plan, y la formación de profesionales sobre el tratamiento de las ITS se recoge en otro apartado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c9") }, {"long_answer": "En relación con la infección por SARS-CoV-2, el Plan Estratégico para la Prevención y Control del VIH y las ITS promueve la vacunación de las personas con VIH y otras ITS, ya que algunas de ellas, sobre todo las que tienen recuentos bajos de linfocitos CD4 o carga viral no suprimida, pueden presentar mayor riesgo de evolución grave. La vacunación es segura en personas con VIH y forma parte de su atención integral. La formación en prevención de factores de riesgo, el desarrollo de herramientas digitales y la formación de profesionales sobre el tratamiento son acciones del plan, pero no las que se refieren específicamente a la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ca") }, {"long_answer": "El apartado 4.1 del Plan Estratégico para la Prevención y Control del VIH y las ITS se centra en la calidad de vida de las personas con VIH y propone mejorar la recogida de información sobre calidad de vida en los diferentes sistemas de información sanitaria, ya que, con el tratamiento antirretroviral eficaz, la calidad de vida se ha convertido en el llamado cuarto 90, más allá de la supresión viral. Facilitar el acceso a la justicia gratuita y promover la equidad e igualdad de trato se vinculan con la lucha contra el estigma y la discriminación, y la evaluación del riesgo de COVID-19 en el personal sanitario no es una acción del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774cb") }, {"long_answer": "En el apartado 3.5 del Plan Estratégico para la Prevención y Control del VIH y las ITS se promueve la formación de los profesionales sanitarios sobre las complicaciones asociadas a las infecciones de transmisión sexual, como la enfermedad inflamatoria pélvica, la infertilidad, las complicaciones neurológicas de la sífilis o la transmisión vertical, para mejorar su diagnóstico y manejo. La formación sobre el tratamiento del VIH, sobre estilos de vida saludables o sobre resistencias antibióticas forma parte de otras líneas del plan, pero no es la acción formativa recogida específicamente en este apartado, centrado en las ITS y sus complicaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ce") }, {"question": "Entre las actuaciones de colaboración recogidas en el Plan Estratégico para la Prevención y Control del VIH y las ITS, ¿cuál se articula como coordinación institucional y NO como contrato o convenio?", "long_answer": "La coordinación con el Centro Nacional de Epidemiología del Instituto de Salud Carlos III es una actuación de coordinación institucional entre organismos públicos, centrada en la vigilancia epidemiológica del VIH y las ITS, y no un contrato ni un convenio. Las demás opciones sí son instrumentos de colaboración formalizados: el mantenimiento del contrato entre la Asociación Española de Pediatría y la Asociación Nacional de Fabricantes de Productos de Dietética Infantil, el convenio con la Universidad Rey Juan Carlos para un máster sobre infección por VIH y el contrato con la Sociedad Española de Infectología Pediátrica para el análisis clínico-epidemiológico en niños y adolescentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774cf") }, {"long_answer": "El Plan Estratégico para la Prevención y Control del VIH y las ITS se desarrolla mediante planificaciones operativas anuales, y el instrumento previsto para medir el avance de las acciones propuestas en ellas es el Comité de Seguimiento del Plan, encargado de revisar los indicadores y el grado de cumplimiento. La Comisión Nacional de Coordinación y Seguimiento de Programas de Prevención del Sida es el órgano de coordinación entre el Ministerio y las comunidades autónomas, el convenio con la Universidad Rey Juan Carlos es un instrumento formativo y la coordinación con la industria farmacéutica no se plantea como mecanismo de seguimiento del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d0") }, {"long_answer": "El Comité Asesor y Consultivo de ONG (COAC) agrupa a las organizaciones no gubernamentales que trabajan en VIH e ITS y constituye un espacio de debate y revisión conjunta que complementa y enriquece las acciones que se ponen en marcha desde la División de Control de VIH, ITS, Hepatitis virales y Tuberculosis, aportando la perspectiva de la sociedad civil y de las personas afectadas. El contrato con la Sociedad Española de Infectología Pediátrica y el convenio con la Universidad Rey Juan Carlos son instrumentos de colaboración técnica o formativa, y la coordinación con el Centro Nacional de Epidemiología se orienta a la vigilancia epidemiológica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d8") }, {"long_answer": "El Convenio Marco de la OMS para el Control del Tabaco se adoptó en la Asamblea Mundial de la Salud de 2003 y entró en vigor el 27 de febrero de 2005, noventa días después de que se depositara el cuadragésimo instrumento de ratificación. Fue el primer tratado internacional de salud pública negociado bajo los auspicios de la OMS. España lo ratificó en 2004 y ese mismo año 2005 aprobó la Ley 28/2005 de medidas sanitarias frente al tabaquismo. El año 2001 corresponde a la fase de negociación, y los años 2010 y 2015 son posteriores a su entrada en vigor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e1") }, {"long_answer": "El Plan Integral de Prevención y Control del Tabaquismo señala que las mayores prevalencias de consumo se dan en los tramos de edad intermedios, aproximadamente de 25 a 64 años, y que donde se observa más variabilidad es en el grupo de 15 a 24 años, cuya prevalencia ha bajado del 26,9% al 15% en poco más de diez años. Esta variabilidad refleja la sensibilidad de los jóvenes a las medidas regulatorias, al precio y a la aparición de nuevos productos. Los tramos de 25-34, 35-44 y 45-54 años presentan prevalencias más elevadas pero más estables a lo largo del tiempo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e3") }, {"long_answer": "Según los datos de la encuesta ESTUDES recogidos en el Plan Integral de Prevención y Control del Tabaquismo, el consumo de cigarrillos electrónicos entre estudiantes de secundaria de 14 a 18 años ha experimentado un fuerte repunte, y las prevalencias aumentan con la edad, alcanzando sus valores más altos en el tramo de 17-18 años. A esa edad confluyen mayor autonomía, mayor acceso a los productos y mayor influencia del grupo de iguales. El tramo de 15-16 años presenta cifras menores, y los de 19-20 y 21-22 años quedan fuera de la población escolar de secundaria que analiza esta encuesta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e8") }, {"long_answer": "La encuesta EDADES 2022, sobre alcohol y otras drogas en población de 15 a 64 años, recoge la percepción del riesgo asociado a distintas conductas, entre ellas fumar un paquete de tabaco diario, y el Plan Integral de Prevención y Control del Tabaquismo utiliza este dato para ilustrar la percepción de la población sobre los daños del tabaco. Según la cifra recogida, el 32,7% de las personas respondió en ese sentido, lo que muestra que una parte relevante de la población no percibe en toda su magnitud el riesgo de un consumo diario elevado. Los valores del 40,5%, 25,8% y 18,3% no se corresponden con el dato recogido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774eb") }, {"long_answer": "Entre los principios del Plan Integral de Prevención y Control del Tabaquismo para mejorar la eficiencia y la armonización territorial figura incluir el tratamiento del tabaquismo en la cartera de servicios de todas las comunidades autónomas, de modo que cualquier persona fumadora tenga acceso a las mismas prestaciones de deshabituación, con independencia de su lugar de residencia, evitando desigualdades territoriales. Desarrollar planes de formación continuada, coordinar mejor los ámbitos asistenciales y establecer indicadores de actividad son medidas útiles del plan, pero no responden específicamente al principio de armonización territorial de las prestaciones entre comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774f1") }, {"long_answer": "Las mujeres que dejan de fumar refieren con frecuencia como principal motivación el deseo de mejorar su salud, tanto la propia como, en determinadas etapas, la de su descendencia, por ejemplo durante la planificación del embarazo, la gestación o la crianza. El Plan Integral de Prevención y Control del Tabaquismo destaca que el tabaquismo tiene condicionantes de género tanto en el inicio como en el abandono, lo que obliga a adaptar las intervenciones. La presión social, el miedo al juicio de los demás o las razones económicas pueden influir en la decisión, pero no son la motivación más frecuente descrita en las mujeres."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774f3") }, {"long_answer": "El análisis de los factores socioeconómicos del abandono del tabaco recogido en el Plan Integral de Prevención y Control del Tabaquismo indica que, en los hombres, la situación laboral parece marcar diferencias en el abandono: los hombres ocupados abandonan el consumo en mayor proporción que los desempleados, en quienes la situación de desempleo se asocia a mayor estrés y menor acceso a recursos. El plan subraya que el tabaquismo tiene condicionantes propios de género en el inicio y en el abandono. El nivel de renta, el nivel de estudios y la clase social influyen en la prevalencia, pero no se señalan como el factor diferencial del abandono masculino."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774f9") }, {"long_answer": "El Reino Unido ha planteado la estrategia de generaciones libres de tabaco, que propone prohibir de forma progresiva la venta de tabaco a las personas nacidas a partir de una fecha determinada, de modo que nunca puedan adquirirlo legalmente. El Plan Integral de Prevención y Control del Tabaquismo la cita como referente internacional y comparte la meta de una generación libre de tabaco para 2040. Estados Unidos ha adoptado otras medidas, como restricciones de sabores o elevar la edad mínima de venta a 21 años, Francia ha centrado su política en precios y empaquetado, y España no ha planteado esta estrategia de prohibición por cohortes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ff") }, {"long_answer": "El Plan Integral de Prevención y Control del Tabaquismo considera fundamental reconocer el tabaquismo como una enfermedad crónica, adictiva y recidivante, y no solo como un hábito, para reducir la morbimortalidad atribuible al tabaco. Este reconocimiento implica que el diagnóstico y el tratamiento de la dependencia deben formar parte de la atención sanitaria habitual, con intervenciones en todos los niveles asistenciales y acceso a tratamiento farmacológico financiado. Promover el consumo, aumentar su prevalencia o desatender la importancia de una política de abordaje del problema son actuaciones contrarias a los objetivos del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977502") }, {"long_answer": "Entre los objetivos del Plan Integral de Prevención y Control del Tabaquismo figura incrementar en un 3% el porcentaje de personas exfumadoras para el horizonte de 2025, lo que equivale a aumentar la proporción de quienes han dejado de fumar con respecto al total de personas que han fumado alguna vez. Este objetivo se vincula a las medidas de fomento del abandono, como la intervención en todos los niveles asistenciales y la financiación del tratamiento farmacológico. Los porcentajes del 1%, 5% o 10% no corresponden a la meta establecida en el plan para el número de personas exfumadoras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977508") }, {"long_answer": "El informe de la OMS El tabaco y su impacto medioambiental, citado en el Plan Integral de Prevención y Control del Tabaquismo, señala que los residuos de tabaco, especialmente las colillas, contienen más de 7.000 sustancias químicas tóxicas, entre ellas nicotina, metales pesados, hidrocarburos aromáticos policíclicos y sustancias cancerígenas, que se liberan al suelo y al agua y afectan a los ecosistemas. Además, los filtros están formados por acetato de celulosa, un plástico de lenta degradación. No contienen sustancias beneficiosas para el medio ambiente ni inofensivas para el ser humano, y la cifra de menos de 1.000 sustancias infravalora su composición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97750b") }, {"option_2": "Establece medidas para reducir su impacto ambiental, como el marcado obligatorio y la responsabilidad ampliada del productor", "long_answer": "La Directiva (UE) 2019/904 sobre plásticos de un solo uso incluye los productos del tabaco con filtro, ya que los filtros de acetato de celulosa son plásticos y las colillas son uno de los residuos más abundantes en playas y entornos naturales. Para reducir su impacto ambiental establece el marcado obligatorio en el envase que informe del contenido plástico y del daño causado al tirarlos, y la responsabilidad ampliada del productor, que obliga a la industria a sufragar la recogida y limpieza de estos residuos y las campañas de concienciación. No busca incrementar su uso ni subvencionar su producción, y sí contempla medidas ambientales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977518") }, {"option_4": "Ampliar legislativamente los espacios sin humo de tabaco", "long_answer": "La promoción de la investigación aplicada y la monitorización del tabaquismo requiere disponer de datos actualizados sobre el mercado y los patrones de consumo, por lo que el Plan Integral de Prevención y Control del Tabaquismo contempla la realización de encuestas y estudios de mercado sobre preferencias de consumo, útiles para detectar nuevos productos, sabores o formas de uso y orientar la regulación. Colaborar con el Ministerio para la Transición Ecológica en campañas medioambientales y subvencionar proyectos de prevención primaria en adolescentes pertenecen a otras líneas, y ampliar legislativamente los espacios sin humo es una medida de protección frente a la exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977519") }, {"option_2": "Incluir la intervención en tabaquismo en la cartera de servicios hospitalaria", "long_answer": "El Plan Integral de Prevención y Control del Tabaquismo plantea, dentro de la protección de la población, el objetivo de reducir la exposición ambiental a las emisiones de tabaco y productos relacionados en espacios públicos, incluidos espacios al aire libre como terrazas, entornos escolares o parques infantiles, dado que no existe un nivel seguro de exposición al humo ambiental. Garantizar la equidad en el acceso a programas de cesación, incluir la intervención en tabaquismo en la cartera hospitalaria e incrementar el porcentaje de personas exfumadoras son objetivos relacionados con el fomento del abandono, no con la reducción de la exposición ambiental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977521") }, {"long_answer": "El virus del sarampión, un Morbillivirus cuyo único reservorio es el ser humano, se transmite por contacto con las secreciones nasales o faríngeas de las personas infectadas, a través de gotas respiratorias y también por vía aérea mediante aerosoles que pueden permanecer en suspensión en el ambiente hasta dos horas. Es una de las enfermedades más contagiosas que se conocen, con un número reproductivo básico de 12 a 18, lo que exige coberturas vacunales superiores al 95% con dos dosis. No se transmite por agua contaminada, picaduras de insectos ni contacto con animales, al no existir vector ni reservorio animal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977527") }, {"long_answer": "El Plan Estratégico para la Eliminación del Sarampión y la Rubeola recomienda, como base de las estrategias de eliminación, fortalecer el programa de vacunación para alcanzar y mantener coberturas iguales o superiores al 95% con dos dosis de triple vírica en todas las cohortes y territorios, y vacunar a los adultos susceptibles. A ello se suma una vigilancia epidemiológica de alta calidad. Reducir la capacidad de vigilancia, aumentar la transmisión endémica o disminuir la información sobre los beneficios de la vacunación son medidas contrarias a la eliminación y facilitarían la reaparición de brotes y la pérdida del estatus de eliminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97752a") }, {"long_answer": "Según los datos de la Comisión Regional de Verificación de la OMS para Europa recogidos en el Plan Estratégico para la Eliminación del Sarampión y la Rubeola, más de 20 países de la Región Europea de la OMS han logrado alcanzar o mantener el estado de eliminación del sarampión endémico, entre ellos España, que obtuvo la certificación de la eliminación tras demostrar la ausencia de transmisión endémica durante al menos 36 meses. No obstante, varios países de la región mantienen transmisión endémica o la han restablecido, lo que favorece los casos importados. Menos de 10 o entre 10 y 20 países infravaloran la cifra real, que el documento sí especifica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97752c") }, {"long_answer": "Según los datos de la RENAVE recogidos en el Plan Estratégico para la Eliminación del Sarampión y la Rubeola, la edad media de los casos de sarampión adecuadamente vacunados entre 2014 y 2018 fue de 25,8 años. Se trata de adultos jóvenes que, pese a haber recibido la vacuna, enfermaron, lo que se relaciona con fallos vacunales secundarios por pérdida de inmunidad con el tiempo en un contexto de escasa circulación del virus, y en general cursan con cuadros más leves. Las edades de 20,1, 30,4 y 35,7 años no coinciden con el dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97752e") }, {"long_answer": "Según la tabla 5a del Plan Estratégico para la Eliminación del Sarampión y la Rubeola, el 42,9% de los enfermeros que tuvieron sarampión habían recibido dos o más dosis de vacuna. Este dato indica que, en profesionales con exposición intensa y repetida al virus, pueden producirse fallos vacunales, aunque estos casos suelen ser más leves y menos transmisibles. Aun así, la vacunación con dos dosis de triple vírica sigue siendo la principal medida de protección del personal sanitario y de los pacientes. Los porcentajes del 25,0%, 32,1% y 71,4% no corresponden al valor de la tabla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97752f") }, {"long_answer": "El Plan Estratégico para la Eliminación del Sarampión y la Rubeola destaca la vacunación del personal sanitario por varias razones simultáneas: evita la propagación del virus en la comunidad y la transmisión nosocomial, reduce las complicaciones de la enfermedad en los propios profesionales, que tienen una exposición mayor que la población general, y protege a los pacientes vulnerables, como lactantes no vacunados, embarazadas o personas inmunodeprimidas, que no pueden recibir la vacuna o responden peor a ella. Por eso la respuesta correcta es todas las anteriores. Se recomienda comprobar la inmunidad de los trabajadores sanitarios y vacunar con dos dosis a los susceptibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977530") }, {"long_answer": "Según los datos de la RENAVE recogidos en el Plan Estratégico para la Eliminación del Sarampión y la Rubeola, el 13,8% de los casos de sarampión notificados entre 2014 y 2018 se diagnosticaron en personas que trabajaban en el ámbito sanitario. Es una proporción muy elevada en relación con el peso de este colectivo en la población, que refleja su mayor exposición y la existencia de profesionales susceptibles, y justifica la recomendación de verificar y completar la vacunación del personal sanitario. Los porcentajes del 10,3%, 20,6% y 27,1% no corresponden al dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977533") }, {"long_answer": "Para fortalecer la vacunación sistemática con triple vírica, el Plan Estratégico para la Eliminación del Sarampión y la Rubeola propone generar recordatorios de vacunación, por ejemplo mediante los registros de vacunación y los sistemas de información de atención primaria, para captar a la población con dosis pendientes y evitar retrasos. Los estudios de seroprevalencia y la evaluación de coberturas son actividades de vigilancia y monitorización, no de refuerzo directo de la vacunación sistemática. Administrar la vacuna a todas las personas con independencia de su historial vacunal no es una recomendación del plan, que se basa en completar dos dosis en susceptibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977539") }, {"long_answer": "Tras la evaluación de los Informes Periódicos de Seguridad de las vacunas frente al sarampión y la rubeola, se concluyó que no era necesario realizar actividades adicionales de gestión de riesgos específicas, porque no se había constatado un cambio en la naturaleza, la frecuencia o la gravedad de los acontecimientos adversos asociados a estas vacunas, por lo que su perfil de seguridad seguía siendo favorable. No se debe a que las vacunas carezcan de riesgos, ya que ningún medicamento está libre de ellos, ni a la ineficacia de las actividades de gestión de riesgos, ni a la falta de recursos para realizarlas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97753d") }, {"option_2": "Determinar la eficacia del tratamiento antiviral específico del SRC", "long_answer": "La vigilancia del síndrome de rubeola congénita tiene como propósito identificar y aislar a tiempo al lactante infectado, ya que estos niños pueden excretar el virus durante meses, incluso hasta un año, y transmitirlo a personas susceptibles, especialmente a mujeres embarazadas. Además, la vigilancia permite valorar el impacto de la vacunación. No existe un tratamiento antiviral específico del SRC, por lo que no puede evaluarse su eficacia. La notificación a la OMS se hace a través de los informes nacionales y no es el propósito de la vigilancia, y estudiar abortos y muertes fetales es una actividad de investigación de casos, no su finalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97753e") }, {"long_answer": "El objetivo general del sistema de vigilancia del sarampión, la rubeola y el síndrome de rubeola congénita es proporcionar la información necesaria para guiar la planificación y evaluar las actividades y programas establecidos, en especial los de vacunación, con vistas a alcanzar y mantener la eliminación. Identificar rápidamente la circulación de los virus y monitorizar la exhaustividad de la notificación a la RENAVE son objetivos específicos o indicadores de calidad del sistema de vigilancia, y difundir la importancia de la eliminación es una actividad de comunicación, no el objetivo general de la vigilancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977552") }, {"long_answer": "La escala de Maddox clasifica la flebitis en seis niveles, de 0 a 5: el 0 corresponde a ausencia de dolor, eritema, hinchazón o cordón palpable; los niveles 1 a 3 describen grados progresivos de dolor, eritema e hinchazón; el 4 añade cordón venoso palpable de menos de 6 cm; y el 5, cordón venoso de más de 6 cm, con posible trombosis y supuración. Esta graduación permite actuar precozmente, vigilando en los grados bajos y retirando el catéter en los más altos. Las opciones de 3, 5 u 8 niveles no se ajustan a la estructura de la escala, que va de 0 a 5."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977557") }, {"answer": 2, "long_answer": "El prefijo DOI 10.4067/S0716-1018 corresponde a la Revista Chilena de Infectología, publicada en SciELO Chile, y el identificador 10.4067/S0716-10182014000600004 pertenece al artículo de Véliz, Vergara y Fica, Evaluación de las condiciones de manejo de catéteres vasculares periféricos en pacientes adultos, publicado en 2014. El artículo de Martín Gil y colaboradores sobre la efectividad del tratamiento tópico de la flebitis se publicó en otra revista, las guías de León y Ariza son la conferencia de consenso SEIMC-SEMICYUC, y el proyecto Flebitis Zero es un documento de la Sociedad Española de Medicina Preventiva, Salud Pública e Higiene."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977559") }, {"long_answer": "En los servicios con exposición a radiaciones ionizantes, el dosímetro personal se recambia cada mes, de manera que el servicio de dosimetría lee la dosis acumulada en ese periodo y mantiene actualizado el historial dosimétrico de cada trabajador, de acuerdo con la normativa de protección radiológica. Un recambio semanal sería innecesario y operativamente costoso, mientras que los periodos trimestrales o anuales retrasarían la detección de exposiciones anómalas y dificultarían la adopción precoz de medidas correctoras. Por ello, en los trabajadores expuestos de categoría A la lectura mensual es la práctica habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97755b") }, {"long_answer": "Si la envoltura del dosímetro se rompe, el dosímetro debe devolverse inmediatamente al servicio de protección radiológica o de dosimetría, ya que la lectura podría verse alterada por la luz, la humedad o la contaminación, y es necesario sustituirlo por otro para no interrumpir el registro de dosis del trabajador. No debe seguir utilizándose, porque sus resultados dejarían de ser fiables, ni intentar repararse, ya que cualquier manipulación invalida la lectura. Tampoco debe desecharse, porque se perdería la información de la dosis acumulada hasta ese momento, que forma parte del historial dosimétrico obligatorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97755e") }, {"long_answer": "Según el protocolo de dosimetría del documento, los dosímetros se identifican con un color de pulsera o funda distinto para cada mes, de forma que pueda comprobarse a simple vista que el trabajador lleva el dosímetro del periodo vigente y que se realiza el recambio mensual. Al mes de mayo le corresponde el color negro. Los colores rojo, azul y verde se asignan a otros meses del ciclo. Este sistema facilita el control del recambio por parte del servicio de protección radiológica y evita que se utilicen dosímetros caducados, cuya lectura se asignaría a un periodo erróneo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97755f") }, {"question": "¿En qué dominio de la taxonomía NANDA-I se incluye la clase «Sueño/reposo»?", "option_1": "Actividad/reposo", "option_2": "Crecimiento/desarrollo", "option_3": "Afrontamiento/tolerancia al estrés", "option_4": "Eliminación e intercambio", "long_answer": "En la taxonomía II de NANDA-I, la clase «Sueño/reposo» es la primera clase del dominio 4, Actividad/reposo, que agrupa la producción, conservación, gasto o equilibrio de los recursos energéticos; en ella se incluyen diagnósticos como Insomnio o Trastorno del patrón del sueño. El dominio Crecimiento/desarrollo se refiere a los aumentos de tamaño y a la progresión en las etapas vitales; Afrontamiento/tolerancia al estrés, a las respuestas ante acontecimientos vitales; y Eliminación e intercambio, a las funciones urinaria, gastrointestinal, tegumentaria y respiratoria, sin clases relacionadas con el sueño."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977560") }, {"question": "¿En qué dominio de la taxonomía NANDA-I se incluye la clase «Gestión de la salud»?", "option_1": "Nutrición", "option_2": "Promoción de la salud", "option_3": "Percepción/cognición", "option_4": "Rol/relaciones", "long_answer": "En la taxonomía II de NANDA-I, la clase «Gestión de la salud» pertenece al dominio 1, Promoción de la salud, junto con la clase «Toma de conciencia de la salud». En ella se incluyen diagnósticos como Gestión ineficaz de la salud o Disposición para mejorar la gestión de la salud, que valoran cómo la persona integra en su vida diaria el tratamiento y las conductas de salud. El dominio Nutrición abarca la ingestión, digestión, absorción, metabolismo e hidratación; Percepción/cognición, la atención, orientación, cognición y comunicación; y Rol/relaciones, los vínculos con otras personas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977565") }, {"long_answer": "En el calendario común de vacunación a lo largo de toda la vida, la vacunación frente a la enfermedad meningocócica en lactantes comienza con la vacuna frente al meningococo B a los 2 y 4 meses de edad, con una dosis de refuerzo a los 12 meses, y se completa con la vacuna frente al meningococo C a los 4 meses y la tetravalente ACWY a los 12 meses. Por tanto, las primeras dosis de la pauta del lactante se administran a los 2 y 4 meses. Las edades de 6 y 8, 12 y 15 o 18 y 20 meses no corresponden a la primovacunación meningocócica del calendario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977566") }, {"long_answer": "El calendario común de vacunación a lo largo de toda la vida recomienda la vacunación sistemática frente al herpes zóster con vacuna de subunidades adyuvada (dos dosis separadas al menos dos meses) a partir de los 65 años, comenzando por la cohorte que cumple 65 años y captando progresivamente a las cohortes de mayor edad. A esta edad aumentan la incidencia de herpes zóster y el riesgo de neuralgia postherpética por la inmunosenescencia. Las edades de 55, 60 y 70 años no corresponden a la recomendación de vacunación poblacional, aunque en personas con condiciones de riesgo se vacuna desde los 18 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977567") }, {"long_answer": "En el calendario común de vacunación a lo largo de toda la vida, los adolescentes que no refieran haber pasado la varicela y no estén vacunados deben recibir dos dosis de vacuna frente a la varicela separadas por un intervalo mínimo de cuatro semanas, para completar una protección adecuada; si ya tienen una dosis, solo se administra la segunda. Una sola dosis es insuficiente para prevenir los casos de rotura vacunal, y las pautas de tres o cuatro dosis no existen para esta vacuna. Es una vacuna de virus vivos atenuados, contraindicada en el embarazo y en personas con inmunodepresión grave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97756a") }, {"question": "¿Qué vacuna se recomienda específicamente, con dosis adaptadas y control serológico posterior, en personas con enfermedad renal crónica avanzada y en hemodiálisis?", "option_1": "Fiebre amarilla", "option_2": "Fiebre tifoidea", "option_3": "Hepatitis B", "option_4": "Rabia", "long_answer": "En las personas con enfermedad renal crónica avanzada y en hemodiálisis se recomienda la vacunación frente a la hepatitis B, porque los procedimientos de hemodiálisis suponen un riesgo de transmisión parenteral y la uremia reduce la respuesta inmune; por ello se utilizan vacunas de alta carga antigénica o adyuvadas y se realiza serología posvacunal, con revacunación si no se alcanza un título protector. La fiebre amarilla, la fiebre tifoidea y la rabia son vacunas indicadas por viajes o exposición específica, no por la enfermedad renal, y la fiebre amarilla es además una vacuna atenuada que requiere valoración en inmunodeprimidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97756b") }, {"long_answer": "El calendario de vacunación en grupos de riesgo establece que los adolescentes que no refieran antecedentes de haber pasado la varicela y no hayan sido vacunados deben recibir dos dosis de vacuna frente a la varicela, separadas por un intervalo mínimo de cuatro semanas. Esta pauta proporciona una protección elevada y reduce los fallos vacunales observados con una sola dosis. Si el adolescente tiene una dosis previa, se le administra solo la segunda. No existen pautas de tres ni de cuatro dosis para la vacuna de la varicela, que es de virus vivos atenuados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97757b") }, {"long_answer": "El proceso enfermero consta de cinco etapas: valoración, diagnóstico, planificación, ejecución o implementación y evaluación. En la implementación el plan de cuidados se pone en acción: la enfermera realiza las intervenciones y actividades planificadas, delega cuando procede y registra lo realizado y la respuesta del paciente. En la valoración se recogen y organizan los datos, en la fase diagnóstica se identifican los problemas de salud y se formulan los diagnósticos enfermeros, y en la planificación se establecen prioridades, resultados esperados e intervenciones, pero sin ejecutarlas todavía. La evaluación, por último, compara los resultados obtenidos con los esperados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977581") }, {"long_answer": "En el proyecto Bacteriemia Zero, cada comunidad autónoma designó un equipo coordinador autonómico en el que el médico intensivista asumía la responsabilidad de la formación y la coordinación de los equipos locales de las UCI de su comunidad, en colaboración con la enfermera de cuidados intensivos y el representante de la consejería de sanidad. Este profesional garantizaba la implantación homogénea de las medidas y el registro de datos en ENVIN-HELICS. El representante de pacientes no ejercía funciones de coordinación técnica, el Consejo Ejecutivo actuaba a nivel nacional y el equipo coordinador del hospital trabajaba en el ámbito de su propio centro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977585") }, {"long_answer": "Las recomendaciones del proyecto Bacteriemia Zero establecen como preferente la vena subclavia para la inserción de catéteres venosos centrales, porque es la localización con menor riesgo de infección y de colonización del catéter, además de ofrecer mayor comodidad para el paciente y facilitar los cuidados. Debe evitarse la vena femoral siempre que sea posible por su mayor riesgo de infección y trombosis, y la yugular interna presenta también un riesgo de infección superior al de la subclavia. La elección debe valorar además el riesgo de complicaciones mecánicas, como el neumotórax, que es más frecuente en la punción subclavia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9775a7") }, {"option_2": "Sustituir los sistemas de notificación nacionales por un registro internacional único", "long_answer": "La Estrategia de Seguridad del Paciente del SNS 2015-2020 incluye una línea de colaboración internacional cuyo objetivo específico es fomentar la participación española en foros internacionales sobre seguridad del paciente, como los de la OMS, la Unión Europea o la OCDE, para compartir experiencias, contribuir al desarrollo de recomendaciones comunes y aprender de otros sistemas sanitarios. Sustituir los sistemas de notificación nacionales por un registro internacional único no se contempla en la estrategia, la formación de los profesionales en gestión de riesgos pertenece a la línea de cultura de seguridad, y estimular la participación de los pacientes corresponde a la línea de participación ciudadana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9775b7") }, {"option_2": "Identificar al paciente preguntándole si es la persona cuyo nombre se cita", "long_answer": "La Estrategia de Seguridad del Paciente recomienda como práctica prioritaria utilizar al menos dos identificadores inequívocos, como el nombre y apellidos y la fecha de nacimiento o el número de historia clínica, antes de administrar medicamentos o hemoderivados, extraer muestras o realizar procedimientos. El número de cama o habitación nunca debe usarse como identificador, porque cambia y puede ser compartido. Preguntar al paciente si es la persona cuyo nombre se cita es una práctica insegura, ya que un paciente confuso o con dificultades auditivas puede asentir; debe pedírsele que diga sus datos. La identificación automatizada, como las pulseras con código de barras, se fomenta, no se evita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9775c3") }, {"answer": 2, "long_answer": "El Estudio Nacional sobre los Efectos Adversos ligados a la Hospitalización (ENEAS, 2005), recogido en la Estrategia de Seguridad del Paciente, mostró que el 37,4% de los eventos adversos de los pacientes ingresados estaban relacionados con la medicación, el 25,3% con infecciones nosocomiales y el 25% con problemas técnicos durante un procedimiento. Por tanto, el porcentaje asociado a procedimientos fue del 25%. El 35% se aproxima a los eventos relacionados con la medicación, y el 15% y el 45% no corresponden a ninguna de las categorías principales. El estudio estimó además que el 42,8% de los eventos adversos eran evitables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9775d0") }, {"option_4": "42,8%", "long_answer": "El Estudio Nacional sobre los Efectos Adversos ligados a la Hospitalización (ENEAS), realizado en 2005 en 24 hospitales españoles, encontró una incidencia de pacientes con eventos adversos relacionados directamente con la asistencia hospitalaria del 8,4%, y consideró evitables el 42,8% de ellos, lo que pone de manifiesto un amplio margen de mejora mediante prácticas seguras, como la prevención de errores de medicación, la higiene de manos o la cirugía segura. Las cifras del 15%, 25% y 35% no corresponden a la proporción de eventos adversos evitables, aunque el 25% coincide con los relacionados con procedimientos."});
